library(shiny)

ui <- fluidPage(

  titlePanel("Multiplication Practice"),

  tags$head(
    tags$style(HTML("
      .question {
        font-size: 60px;
        font-weight: bold;
        text-align: center;
        margin-top: 80px;
        margin-bottom: 50px;
      }

      .button-container {
        text-align: center;
      }

      .big-button {
        font-size: 24px;
        padding: 15px 30px;
        margin: 10px;
      }
    "))
  ),

  sidebarLayout(

    sidebarPanel(
      numericInput(
        inputId = "lower",
        label = "Lower number:",
        value = 1,
        min = 0
      ),

      numericInput(
        inputId = "upper",
        label = "Higher number:",
        value = 12,
        min = 1
      )
    ),

    mainPanel(

      div(
        class = "question",
        textOutput("question")
      ),

      div(
        class = "button-container",

        actionButton(
          inputId = "answer",
          label = "Answer",
          class = "big-button btn-success"
        ),

        actionButton(
          inputId = "new_question",
          label = "New Question",
          class = "big-button btn-primary"
        )
      )
    )
  )
)

server <- function(input, output, session) {

  # Store the current question
  question <- reactiveVal(NULL)

  # Keep track of whether the answer is visible
  show_answer <- reactiveVal(FALSE)


  # Function to generate a question
  generate_question <- function() {

    # Get the bounds from the input boxes
    lower <- input$lower
    upper <- input$upper

    # Don't generate a question if the bounds are invalid
    if (is.null(lower) || is.null(upper) || lower > upper) {
      return()
    }

    # num1 is sampled FROM THE SEQUENCE lower:upper
    num1 <- sample(seq(lower, upper), 1)

    # num2 is independently sampled from 1 to 12
    num2 <- sample(seq(1, 12), 1)

    # Store the question
    question(
      list(
        num1 = num1,
        num2 = num2
      )
    )

    # Hide the answer for the new question
    show_answer(FALSE)
  }


  # Generate the first question
  observe({
    generate_question()
  })


  # Generate a new question when button is clicked
  observeEvent(input$new_question, {
    generate_question()
  })


  # Generate a new question if the lower bound changes
  observeEvent(input$lower, {
    generate_question()
  })


  # Generate a new question if the upper bound changes
  observeEvent(input$upper, {
    generate_question()
  })


  # Show the answer
  observeEvent(input$answer, {
    show_answer(TRUE)
  })


  # Display question
  output$question <- renderText({

    q <- question()

    if (is.null(q)) {
      return("")
    }

    if (show_answer()) {

      paste(
        q$num1,
        "x",
        q$num2,
        "=",
        q$num1 * q$num2
      )

    } else {

      paste(
        q$num1,
        "x",
        q$num2,
        "= ?"
      )
    }
  })
}

shinyApp(ui = ui, server = server)

